/* Learning objects are backed by explicit units; mastery is earned in the device. */
'use strict';
const knowledgePositions=new Map();
lessonPosition=function(i){let positions=knowledgePositions.get(state.zone);if(!positions){const candidates=CAT.objects(state.zone).filter(o=>o.x>5&&o.x<95&&o.y>7&&o.y<94&&zoneInfo().stations.every(st=>Math.abs(o.x-st[2])>6||Math.abs(o.y-st[3])>6)&&[[69,67],[47,57],[40,43],[53,48],[66,53]].every(([x,y])=>Math.abs(o.x-x)>7||Math.abs(o.y-y)>7));positions=[];const d=(a,b)=>(a.x-b.x)**2*1.6+(a.y-b.y)**2;while(candidates.length){let best=0,score=-Infinity;for(let n=0;n<candidates.length;n++){const value=positions.length?Math.min(...positions.map(p=>d(p,candidates[n]))):-d({x:49,y:35},candidates[n]);if(value>score){best=n;score=value;}}positions.push(candidates.splice(best,1)[0]);}knowledgePositions.set(state.zone,positions);}return positions[i%positions.length];};
function knowledgeText(l,key){return state.language==='en'?(l.en?.[key]||l[key]||''):(l[key]||'');}
function learningCopy(zh,en){return state.language==='en'?en:zh;}
function unitParts(l){const mode=discoveryProp(l).mode,sets={map:[['指南针','Compass needle',24],['钢铁外壳','Steel housing',11],['磁石','Magnet',29]],assemble:[['主齿轮','Main gear',11],['木匣外壳','Wooden case',35],['转动摇柄','Crank handle',28]],grow:[['小种子','Seed',4],['陶土盆','Clay pot',21],['浇水壶','Watering can',2]],lens:[['透镜','Lens',3],['镜筒','Lens barrel',9],['镜柄','Lens handle',28]],letter:[['信纸','Letter paper',6],['信封','Envelope',15],['封蜡','Sealing wax',7]],stars:[['星屑','Stardust',29],['玻璃瓶','Glass bottle',12],['瓶塞','Bottle stopper',11]]};return sets[mode].map(([zh,en,art],i)=>({name:learningCopy(zh,en),key:['body','example','quote'][i],art}));}
function unitAssembly(l){state.unitAssembly??={};const bank=state.unitAssembly[state.selected]??={};return bank[l.id]??={found:[],placed:[]};}
let assemblyLesson=null,assemblySelected=null,matchSelected=null,matchOrder=[];
const knowledgeCompass=$('useCompass').onclick;
function locateKnowledge(){if(!currentCourse()||studyState().mode!=='learn'){knowledgeCompass();return;}const sec=studySection(),s=studyState(),active=sec.lessons.find(l=>l.id===assemblyLesson&&l.interaction==='assemble'&&!s.carried.includes(l.id)&&!s.deposited.includes(l.id));if(active){const a=unitAssembly(active),part=[0,1,2].find(i=>!a.found.includes(i));if(part!==undefined){const p=lessonPosition(sec.lessons.length+part);pointXY(p.x,p.y);return;}const p=lessonPosition(sec.lessons.indexOf(active));pointXY(p.x,p.y);return;}const next=sec.lessons.findIndex(l=>!s.carried.includes(l.id)&&!s.deposited.includes(l.id));if(next>=0){const p=lessonPosition(next);pointXY(p.x,p.y);}else{pointXY(69,67);openStudyBasket();}};
const knowledgeHUD=renderHUD;
renderHUD=function(){knowledgeHUD();if(currentCourse()&&studyState().mode==='learn')$('useCompass').onclick=locateKnowledge;};
openStudyLesson=function(id,reference=false){const l=currentCourse()?.chapters.flatMap(c=>c.sections.flatMap(s=>s.lessons)).find(l=>l.id===id);if(!l)return;if(!reference&&!studySection().lessons.some(l=>l.id===id)){studyLocked();return;}if(reference&&!studyState().read.includes(id)){studyLocked();return;}
 const assembling=l.interaction==='assemble'&&!reference,parts=unitParts(l),a=unitAssembly(l);assemblyLesson=id;assemblySelected=null;
 modal(`<span class="eyebrow">${assembling?learningCopy('工坊 · 从场景寻找三个部件','Workshop · find three parts in the scene'):learningCopy('知识物件 · 阅读与收集','Knowledge object · read and collect')}</span><h2 id="dialogTitle">${esc(assembling?discoveryProp(l).name:knowledgeText(l,'title'))}</h2>${assembling?`<p class="device-learning-caption">${esc(knowledgeText(l,'title'))}</p>`:''}${assembling?`<p>${learningCopy('部件散落在场景中。逐个打开阅读，收集后送进正确插槽。','The parts are scattered around the scene. Read each one, collect it, then put it in the correct slot.')}</p><div class="assembly-slots">${parts.map((p,i)=>`<button data-unit-slot="${i}" data-drop="unit-slot-${i}" class="${a.placed.includes(i)?'matched':''}">${sprites(p.art)}<strong>${p.name}</strong><small>${a.placed.includes(i)?'✓':learningCopy('等待部件','Waiting for a part')}</small></button>`).join('')}</div><div class="assembly-pocket">${a.found.filter(i=>!a.placed.includes(i)).map(i=>`<button data-unit-held="${i}" draggable="true">${parts[i].name}</button>`).join('')}</div><p id="unitFeedback" role="status">${a.placed.length}/3 ${learningCopy('已组装','assembled')}</p><button id="findUnitParts">${learningCopy('回场景寻找部件','Find the parts in the scene')}</button>`:`<div class="lesson-explanation"><h3>${learningCopy('定义','Definition')}</h3>${studyText(knowledgeText(l,'body'))}</div>${l.example?`<div class="lesson-example"><strong>${learningCopy('应用示例','Example')}</strong><p>${esc(knowledgeText(l,'example'))}</p></div>`:''}`}${l.boundary?`<div class="knowledge-boundary"><strong>${learningCopy('容易混淆的边界','Important distinction')}</strong><p>${esc(knowledgeText(l,'boundary'))}</p></div>`:''}<details class="source-detail"><summary>${learningCopy('学习目标与依据','Learning objective and evidence')}</summary><p>${esc(knowledgeText(l,'quote'))}</p><p>${esc(l.source)}</p>${(l.references||[]).map(url=>`<a href="${esc(url)}" target="_blank" rel="noopener">${esc(new URL(url).hostname)}</a>`).join(' · ')}</details><div class="actions"><button id="leaveLesson">${learningCopy('返回场景','Back to scene')}</button>${reference?'':`<button id="collectLesson" class="primary" ${assembling&&a.placed.length<3?'disabled':''}>${learningCopy('收集这份知识','Collect this knowledge')}</button>`}</div>`,true);
 $('leaveLesson').onclick=close;if($('findUnitParts'))$('findUnitParts').onclick=()=>{close();render();save();};
 document.querySelectorAll('[data-unit-held]').forEach(el=>{el.onclick=()=>{assemblySelected=+el.dataset.unitHeld;$('unitFeedback').textContent=parts[assemblySelected].name+' · '+learningCopy('选择对应插槽','Choose its matching slot');};bindDraggable(el,{unit:id,part:+el.dataset.unitHeld});});
 document.querySelectorAll('[data-unit-slot]').forEach(el=>{el.onclick=()=>placeUnitPart(id,assemblySelected,+el.dataset.unitSlot);bindDrop(el,'unit-slot-'+el.dataset.unitSlot);});
 if($('collectLesson'))$('collectLesson').onclick=()=>{if(assembling&&a.placed.length<3)return;CS.read(studyState(),currentCourse(),id);if(CS.collect(studyState(),currentCourse(),id)){heldFruit=id;close();render();save();}};
};
function placeUnitPart(id,part,slot){const l=studySection().lessons.find(l=>l.id===id);if(!l||!Number.isInteger(part))return;const a=unitAssembly(l);if(!a.found.includes(part)||a.placed.includes(part))return;if(part!==slot){if($('unitFeedback'))$('unitFeedback').textContent=learningCopy('这个部件和插槽不匹配，看看名称再试一次。','That part does not fit this slot. Check the names and try again.');return;}a.placed.push(part);save();openStudyLesson(id);}
function openUnitPart(id,i){const l=studySection().lessons.find(l=>l.id===id);if(!l)return;const p=unitParts(l)[i],a=unitAssembly(l);modal(`<span class="eyebrow">${esc(knowledgeText(l,'title'))} · ${p.name}</span><h2 id="dialogTitle">${[learningCopy('定义','Definition'),learningCopy('应用示例','Example'),learningCopy('学习目标','Learning objective')][i]}</h2><div class="lesson-explanation">${studyText(knowledgeText(l,p.key)||learningCopy('本材料未提供示例，请结合定义理解。','No example was supplied; review the definition.'))}</div><div class="actions"><button id="takeUnitPart" class="primary">${learningCopy('收集部件','Collect part')}</button><button id="partBack">${learningCopy('返回','Back')}</button></div>`);$('partBack').onclick=close;$('takeUnitPart').onclick=()=>{if(!a.found.includes(i))a.found.push(i);save();close();render();};}
const knowledgeRenderLoot=renderLoot;
renderLoot=function(){knowledgeRenderLoot();if(!currentCourse()||studyState().mode!=='learn')return;const sec=studySection();const partHost=document.createElement('div');partHost.id='unitParts';partHost.className='unit-parts-world';partHost.innerHTML=sec.lessons.filter(l=>l.interaction==='assemble'&&l.id===assemblyLesson&&!studyState().carried.includes(l.id)&&!studyState().deposited.includes(l.id)).flatMap((l,j)=>unitParts(l).map((p,i)=>{const a=unitAssembly(l),pos=lessonPosition(sec.lessons.length+j*3+i);return a.found.includes(i)?'':`<button class="study-fruit unit-part" data-unit-part="${l.id}:${i}" style="left:${pos.x}%;top:${pos.y}%" aria-label="${p.name} · ${esc(knowledgeText(l,'title'))}">${sprites(p.art)}<small>${p.name}</small></button>`;})).join('');$('loot').appendChild(partHost);$('partSearchNotice')?.remove();const searching=sec.lessons.find(l=>l.id===assemblyLesson&&l.interaction==='assemble'&&!studyState().carried.includes(l.id)&&!studyState().deposited.includes(l.id)&&unitAssembly(l).found.length<3);if(searching){document.querySelectorAll('[data-study-fruit]').forEach(el=>{el.hidden=true;el.remove();});const notice=document.createElement('div');notice.id='partSearchNotice';notice.className='part-search-notice';notice.innerHTML=`<span>${learningCopy('正在找组装部件，其他知识物件暂时收起。','Finding assembly parts; other knowledge objects are temporarily put away.')}</span><button id="endPartSearch">${learningCopy('返回知识探索','Back to knowledge exploration')}</button>`;$('adventureTray').appendChild(notice);$('endPartSearch').onclick=()=>{assemblyLesson=null;render();save();};}const occupied=new Set([0,1,2].map(i=>lessonPosition(sec.lessons.length+i).id));if(partHost.innerHTML)document.querySelectorAll('[data-object]').forEach(el=>{if(occupied.has(el.dataset.object))el.remove();});document.querySelectorAll('[data-unit-part]').forEach(el=>el.onclick=()=>{const[id,n]=el.dataset.unitPart.split(':');openUnitPart(id,+n);});
 document.querySelectorAll('[data-study-fruit]').forEach(el=>{const l=sec.lessons.find(l=>l.id===el.dataset.studyFruit);if(!l)return;el.title='';el.setAttribute?.('aria-label',knowledgeText(l,'title'));if(sec.id==='1.1'){el.innerHTML=`<span class="knowledge-seed">${['🌰','🌱','🫘','🌾'][sec.lessons.indexOf(l)%4]}</span><small>${esc(knowledgeText(l,'title'))}</small>`;}});
 document.querySelectorAll('[data-object], [data-restored-station]').forEach(el=>{el.removeAttribute?.('title');});
};
function openKnowledgeMatch(){const sec=studySection(),s=studyState();if(!sec.lessons.every(l=>s.deposited.includes(l.id)))return;const p=KnowledgePractice.progress(s,sec);matchSelected=null;matchOrder=KnowledgePractice.shuffle(sec.lessons.map(l=>l.id));showKnowledgeMatch();}
function showKnowledgeMatch(){const sec=studySection(),s=studyState(),p=KnowledgePractice.progress(s,sec),remaining=sec.lessons.filter(l=>p.pairs[l.id]!==l.id),page=remaining.slice(0,5),ids=new Set(page.map(l=>l.id)),right=matchOrder.filter(id=>ids.has(id));if(!right.length&&page.length){matchOrder=KnowledgePractice.shuffle(page.map(l=>l.id));return showKnowledgeMatch();}modal(`<span class="eyebrow">${learningCopy('知识整理 · 理解后才完成','Knowledge workshop · understand before completing')}</span><h2 id="dialogTitle">${sec.id==='1.1'?learningCopy('星芽花房','Starlit Seedhouse'):esc(studyTheme().container)}</h2><p class="device-learning-caption">${learningCopy('学习内容','Learning content')} · ${esc(state.language==='en'?sec.english||sec.title:sec.title)}</p><p>${learningCopy('把左侧概念拖到右侧正确的定义上；也可以先点概念，再点定义。每次展示最多五组，正确配对后刷新下一组。','Drag a concept on the left onto its definition on the right, or select a concept and then its definition. Up to five pairs appear at a time.')}</p><strong>${Object.keys(p.pairs).length}/${sec.lessons.length}</strong><div class="knowledge-matching"><div>${page.map(l=>`<button data-match-term="${l.id}" draggable="true" class="${matchSelected===l.id?'selected':''}">${esc(knowledgeText(l,'title'))}</button>`).join('')}</div><div>${right.map(id=>{const l=sec.lessons.find(l=>l.id===id);return `<button data-match-definition="${id}" data-drop="knowledge-definition-${id}">${esc(knowledgeText(l,'body'))}</button>`;}).join('')}</div></div><p id="matchFeedback" role="status">${remaining.length?'':learningCopy('全部配对正确，可以收好本节装置了。','All pairs are correct. You can now complete this section.')}</p><div class="actions"><button id="matchBack">${learningCopy('稍后继续','Continue later')}</button><button id="finishKnowledgeMatch" class="primary" ${remaining.length?'disabled':''}>${learningCopy('收好装置，完成小节','Keep the device and complete section')}</button></div>`,true);
 document.querySelectorAll('[data-match-term]').forEach(el=>{el.onclick=()=>{matchSelected=el.dataset.matchTerm;document.querySelectorAll('[data-match-term]').forEach(e=>e.classList.toggle('selected',e.dataset.matchTerm===matchSelected));};bindDraggable(el,{knowledgeTerm:el.dataset.matchTerm});});document.querySelectorAll('[data-match-definition]').forEach(el=>{el.onclick=()=>answerKnowledgeMatch(matchSelected,el.dataset.matchDefinition);bindDrop(el,'knowledge-definition-'+el.dataset.matchDefinition);});$('matchBack').onclick=()=>{close();save();};$('finishKnowledgeMatch').onclick=()=>{if(!KnowledgePractice.mastered(s,sec))return;if(CS.seal(s,currentCourse())){heldFruit=null;close();render();save();toast(learningCopy('本节已完成，下一节的知识已出现在场景中。','Section complete. New knowledge is now available in the scene.'));}};
}
function answerKnowledgeMatch(term,definition){if(!term)return;const sec=studySection();if(!KnowledgePractice.pair(studyState(),sec,term,definition)){$('matchFeedback').textContent=learningCopy('还没配对正确。可返回素材箱重读定义，再试一次。','Not a match. Review the definition in your knowledge chest and try again.');save();return;}matchSelected=null;save();showKnowledgeMatch();}
openStudyBasket=function(){const s=studyState(),sec=studySection(),theme=studyTheme(),all=sec.lessons.every(l=>s.deposited.includes(l.id)),carried=sec.lessons.filter(l=>s.carried.includes(l.id)),groups=[...new Set(sec.lessons.map(l=>knowledgeText(l,'category')||sec.english||sec.title))];modal(`<span class="eyebrow">${learningCopy('知识装置 · 先学习，再应用','Knowledge device · learn, then apply')}</span><h2 id="dialogTitle">${sec.id==='1.1'?learningCopy('星芽花房','Starlit Seedhouse'):esc(theme.container)}</h2><p class="device-learning-caption">${learningCopy('学习内容','Learning content')} · Task ${sec.id} · ${esc(state.language==='en'?sec.english||sec.title:sec.title)}</p><div class="basket-count">${sec.lessons.filter(l=>s.deposited.includes(l.id)).length}<small> / ${sec.lessons.length}</small></div><p id="knowledgeDeviceInstruction">${learningCopy('每个物件对应一个明确的知识点。收齐后将概念与定义配对，全部正确才能收好装置。','Each object represents a specific knowledge unit. Collect them, then match every concept to its definition to complete this device.')}</p><div class="study-layout layout-${theme.kind} has-groups">${groups.map(group=>`<section class="study-group"><h3>${esc(group)}</h3>${sec.lessons.filter(l=>(knowledgeText(l,'category')||sec.english||sec.title)===group).map(l=>`<button data-study-slot="${l.id}" class="knowledge-slot ${s.deposited.includes(l.id)?'filed':''}"><small>${s.deposited.includes(l.id)?learningCopy('✓ 已整理','✓ Filed'):s.carried.includes(l.id)?learningCopy('点击归位','Place here'):learningCopy('待收集','Not collected')}</small><strong>${esc(knowledgeText(l,'title'))}</strong></button>`).join('')}</section>`).join('')}</div><div class="actions"><button id="basketBack">${learningCopy('返回场景','Back to scene')}</button><button id="depositCarried" ${carried.length?'':'disabled'}>${learningCopy('整理背包','File collected items')} · ${carried.length}</button><button id="sealBasket" class="primary" ${all&&!s.sealed.includes(sec.id)?'':'disabled'}>${learningCopy('打开概念与定义配对','Match concepts with definitions')}</button></div>`,true);$('basketBack').onclick=close;$('depositCarried').onclick=()=>{for(const l of carried)CS.deposit(s,currentCourse(),l.id);heldFruit=null;render();save();openStudyBasket();};$('sealBasket').onclick=openKnowledgeMatch;document.querySelectorAll('[data-study-slot]').forEach(el=>el.onclick=()=>{const id=el.dataset.studySlot;if(s.deposited.includes(id)){openStudyLesson(id,true);return;}if(s.carried.includes(id)){putStudyFruit(id);openStudyBasket();return;}close();const pos=lessonPosition(sec.lessons.findIndex(l=>l.id===id));pointXY(pos.x,pos.y);toast(learningCopy('去光圈附近找找这个知识物件。','Look near the marker for this knowledge item.'));});};
const knowledgeDrag=applyDrag;
applyDrag=function(data,kind,category){if(data?.unit){if(kind.startsWith('unit-slot-'))placeUnitPart(data.unit,data.part,+kind.slice(10));return;}if(data?.knowledgeTerm){if(kind.startsWith('knowledge-definition-'))answerKnowledgeMatch(data.knowledgeTerm,kind.slice(21));return;}knowledgeDrag(data,kind,category);};
const knowledgeSeal=CS.seal;
CS.seal=function(s,course){const sec=course.chapters[s.chapter].sections[s.section];if(!s.sealed.includes(sec.id)&&!KnowledgePractice.mastered(s,sec))return false;return knowledgeSeal(s,course);};
const knowledgeRestore=L.restore;
L.restore=function(raw){let input=raw;try{const candidate=typeof raw==='string'?JSON.parse(raw):JSON.parse(JSON.stringify(raw));const old=candidate.chapterStudies?.[EXAM_ID];if(old?.sealed?.includes('1.1')&&!old.deposited.includes('1.1-lesson-16')){old.previousResults??=[];old.previousResults.push(...old.assessments.filter(a=>a.chapter===0));old.assessments=old.assessments.filter(a=>a.chapter!==0);old.sealed=old.sealed.filter(id=>id!=='1.1');old.submitted=old.submitted.filter(i=>i!==0);if(old.chapterViews?.[0])old.chapterViews[0]={section:0,mode:'learn',round:null};if(old.chapter===0){old.section=0;old.mode='learn';old.round=null;}input=candidate;}}catch{return null;}const s=knowledgeRestore(input);if(!s)return null;for(const[bid,p]of Object.entries(s.chapterStudies||{})){const b=s.banks.find(b=>b.id===bid),c=b?.syllabus||(bid===EXAM_ID?StrategistCourse:null);if(!c||!KnowledgePractice.validate(p,c))return null;}if(s.unitAssembly!==undefined){if(!s.unitAssembly||typeof s.unitAssembly!=='object'||Array.isArray(s.unitAssembly))return null;for(const[bid,entries]of Object.entries(s.unitAssembly)){const b=s.banks.find(b=>b.id===bid),c=b?.syllabus||(bid===EXAM_ID?StrategistCourse:null);if(!c||!entries||typeof entries!=='object'||Array.isArray(entries))return null;for(const[id,p]of Object.entries(entries)){if(!c.chapters.some(ch=>ch.sections.some(sec=>sec.lessons.some(l=>l.id===id)))||!p||!['found','placed'].every(k=>Array.isArray(p[k])&&new Set(p[k]).size===p[k].length&&p[k].every(n=>[0,1,2].includes(n)))||p.placed.some(n=>!p.found.includes(n)))return null;}}}return s;};
// One hover label only: no native title + pseudo tooltip + label stack.
function replayAwayChapter(id){modal(`<h2 id="dialogTitle">${learningCopy('重新开始这一章？','Restart this chapter?')}</h2><p>${learningCopy('本章任务和风景手帐将重新开始，其他章节的进度会保留。','This chapter and its scenery journal will restart. Other chapters keep their progress.')}</p><div class="actions"><button id="confirmChapterReplay" class="primary">${learningCopy('重新开始','Restart')}</button><button id="cancelChapterReplay">${learningCopy('继续原进度','Keep current progress')}</button></div>`);$('cancelChapterReplay').onclick=close;$('confirmChapterReplay').onclick=()=>{state.awayGames[id]=AA.fresh();if(state.sceneExtras)delete state.sceneExtras[id];selectedAwayItem=null;close();save();openAwayScene(id);};}
const knowledgeAway=openAwayScene;
openAwayScene=function(id,message=''){knowledgeAway(id,message);if(!activeAwayScene)return;const toolbar=$('awayScene').querySelector?.('.away-switches')||$('awayScene'),button=document.createElement('button');button.id='replayAwayChapter';button.textContent=learningCopy('重新开始本章','Restart chapter');button.onclick=()=>replayAwayChapter(id);toolbar.appendChild(button);document.querySelectorAll('[data-future-device]').forEach(el=>el.removeAttribute?.('title'));};
function replayStudyChapter(){const s=studyState(),course=currentCourse(),chapter=s.chapter;modal(`<h2 id="dialogTitle">${learningCopy('重新学习这一章？','Restart this learning chapter?')}</h2><p>${learningCopy('本章收集、学习任务和成绩将重新开始。其他章节保留。','Restart collection, learning tasks and assessment in this chapter. Other chapters keep their progress.')}</p><div class="actions"><button id="confirmStudyReplay" class="primary">${learningCopy('重新开始','Restart')}</button><button id="cancelStudyReplay">${learningCopy('继续原进度','Keep progress')}</button></div>`);$('cancelStudyReplay').onclick=close;$('confirmStudyReplay').onclick=()=>{const secs=course.chapters[chapter].sections,ids=new Set(secs.flatMap(sec=>sec.lessons.map(l=>l.id))),sectionIds=new Set(secs.map(sec=>sec.id));for(const k of ['read','carried','deposited'])s[k]=s[k].filter(id=>!ids.has(id));s.sealed=s.sealed.filter(id=>!sectionIds.has(id));s.submitted=s.submitted.filter(i=>i!==chapter);s.assessments=s.assessments.filter(a=>a.chapter!==chapter);for(const c of CS.pool(s,course,L.bank(state).cards))delete s.records[c.id];if(s.practiceRuns)delete s.practiceRuns[chapter];if(s.chapterViews)delete s.chapterViews[chapter];if(s.practiceStarted)s.practiceStarted=s.practiceStarted.filter(id=>!sectionIds.has(id));for(const id of sectionIds)if(s.knowledgeMatches)delete s.knowledgeMatches[id];for(const id of ids){if(state.unitAssembly?.[state.selected])delete state.unitAssembly[state.selected][id];if(state.discoveryRead?.[state.selected])delete state.discoveryRead[state.selected][id];}s.section=0;s.mode='learn';s.round=null;heldFruit=null;close();renderWorld();save();};}
const knowledgeDock=renderExamDock;
renderExamDock=function(){knowledgeDock();if(!currentCourse())return;const b=document.createElement('button');b.id='replayStudyChapter';b.textContent=learningCopy('重玩本章','Replay chapter');b.onclick=replayStudyChapter;$('chapterDock').appendChild(b);};
